#!/bin/bash#============================================================================# ORCA AI Accelerator Series — Build & Lint Script# Usage: ./build_all.sh [target]#   target: all (default) | kestrel | falcon | hawk | phoenix | phoenix-e | phoenix-plus | lint | clean#============================================================================set -eSCRIPT_DIR=$(cd $(dirname ${BASH_SOURCE[0]}) && pwd)ROOT_DIR=$(cd ${SCRIPT_DIR}/.. && pwd)VERILATOR=${VERILATOR:-verilator}SV2V=${SV2V:-sv2v}TARGET=${1:-all}echo '=============================================================='echo '  ORCA AI Accelerator Series — Build & Verification Script'echo '  v1.2 (Kestrel + Falcon + Hawk + Phoenix + Phoenix-E + Phoenix+)'echo '=============================================================='echo ''# Colors for outputRED='033[0;31m'GREEN='033[0;32m'YELLOW='033[1;33m'NC='033[0m' # No Colorfunction info() { echo -e '${YELLOW}[INFO]${NC} $1'; }function ok()   { echo -e '${GREEN}[OK]${NC}   $1'; }function err()  { echo -e '${RED}[ERR]${NC}  $1'; }#----------------------------------------------------------------------------# Clean#----------------------------------------------------------------------------if [ '${TARGET}' = 'clean' ]; then    info 'Cleaning build artifacts...'    rm -rf ${ROOT_DIR}/build    rm -rf ${ROOT_DIR}/obj_dir    ok 'Clean complete'    exit 0fi#----------------------------------------------------------------------------# Create build directory#----------------------------------------------------------------------------mkdir -p ${ROOT_DIR}/build/{kestrel,falcon,hawk,phoenix,phoenix_e,phoenix_plus}#----------------------------------------------------------------------------# v5.0 Kestrel Lint#----------------------------------------------------------------------------function lint_kestrel() {    info '[1/7] Linting Kestrel NPU v5.0...'    ${VERILATOR} --lint-only -Wall -Wno-DECLFILENAME -Wno-WIDTHTRUNC -Wno-WIDTHEXPAND        -I${ROOT_DIR}/v5_0_kestrel/rtl        ${ROOT_DIR}/v5_0_kestrel/rtl/orca_npu_v5.sv        --top-module orca_npu_v5        2>&1 | tee ${ROOT_DIR}/build/kestrel/lint.log    if [ ${PIPESTATUS[0]} -eq 0 ]; then        ok 'Kestrel NPU lint PASSED'    else        err 'Kestrel NPU lint FAILED'        exit 1    fi}#----------------------------------------------------------------------------# v5.1 Falcon Lint#----------------------------------------------------------------------------function lint_falcon() {    info '[2/7] Linting Falcon NPU v5.1...'    ${VERILATOR} --lint-only -Wall -Wno-DECLFILENAME -Wno-WIDTHTRUNC -Wno-WIDTHEXPAND        -I${ROOT_DIR}/v5_1_falcon/rtl        ${ROOT_DIR}/v5_1_falcon/rtl/orca_npu_v5_1.sv        --top-module orca_npu_v5_1        2>&1 | tee ${ROOT_DIR}/build/falcon/lint.log    if [ ${PIPESTATUS[0]} -eq 0 ]; then        ok 'Falcon NPU lint PASSED'    else        err 'Falcon NPU lint FAILED'        exit 1    fi}#----------------------------------------------------------------------------# v5.2 Hawk Lint#----------------------------------------------------------------------------function lint_hawk() {    info '[3/7] Linting Hawk NPU v5.2...'    ${VERILATOR} --lint-only -Wall -Wno-DECLFILENAME -Wno-WIDTHTRUNC -Wno-WIDTHEXPAND        -I${ROOT_DIR}/v5_2_hawk/rtl        ${ROOT_DIR}/v5_2_hawk/rtl/orca_npu_v5_2.sv        --top-module orca_npu_v5_2        2>&1 | tee ${ROOT_DIR}/build/hawk/lint.log    if [ ${PIPESTATUS[0]} -eq 0 ]; then        ok 'Hawk NPU lint PASSED'    else        err 'Hawk NPU lint FAILED'        exit 1    fi}#----------------------------------------------------------------------------# v6.0 Phoenix Lint#----------------------------------------------------------------------------function lint_phoenix() {    info '[4/7] Linting Phoenix TPE+AME v6.0...'    ${VERILATOR} --lint-only -Wall -Wno-DECLFILENAME -Wno-WIDTHTRUNC -Wno-WIDTHEXPAND        -I${ROOT_DIR}/v6_0_phoenix/rtl        ${ROOT_DIR}/v6_0_phoenix/rtl/orca_tpe_v6.sv        --top-module orca_tpe_v6        2>&1 | tee ${ROOT_DIR}/build/phoenix/lint_tpe.log    if [ ${PIPESTATUS[0]} -eq 0 ]; then        ok 'Phoenix TPE lint PASSED'    else        err 'Phoenix TPE lint FAILED'        exit 1    fi    ${VERILATOR} --lint-only -Wall -Wno-DECLFILENAME -Wno-WIDTHTRUNC -Wno-WIDTHEXPAND        -I${ROOT_DIR}/v6_0_phoenix/rtl        ${ROOT_DIR}/v6_0_phoenix/rtl/orca_ame_v6.sv        --top-module orca_ame_v6        2>&1 | tee ${ROOT_DIR}/build/phoenix/lint_ame.log    if [ ${PIPESTATUS[0]} -eq 0 ]; then        ok 'Phoenix AME lint PASSED'    else        err 'Phoenix AME lint FAILED'        exit 1    fi}#----------------------------------------------------------------------------# v6.1 Phoenix-E Lint#----------------------------------------------------------------------------function lint_phoenix_e() {    info '[5/7] Linting Phoenix-E TPE+AME v6.1...'    ${VERILATOR} --lint-only -Wall -Wno-DECLFILENAME -Wno-WIDTHTRUNC -Wno-WIDTHEXPAND        -I${ROOT_DIR}/v6_1_phoenix_e/rtl        ${ROOT_DIR}/v6_1_phoenix_e/rtl/orca_tpe_v6_1.sv        --top-module orca_tpe_v6_1        2>&1 | tee ${ROOT_DIR}/build/phoenix_e/lint_tpe.log    if [ ${PIPESTATUS[0]} -eq 0 ]; then        ok 'Phoenix-E TPE lint PASSED'    else        err 'Phoenix-E TPE lint FAILED'        exit 1    fi    ${VERILATOR} --lint-only -Wall -Wno-DECLFILENAME -Wno-WIDTHTRUNC -Wno-WIDTHEXPAND        -I${ROOT_DIR}/v6_1_phoenix_e/rtl        ${ROOT_DIR}/v6_1_phoenix_e/rtl/orca_ame_v6_1.sv        --top-module orca_ame_v6_1        2>&1 | tee ${ROOT_DIR}/build/phoenix_e/lint_ame.log    if [ ${PIPESTATUS[0]} -eq 0 ]; then        ok 'Phoenix-E AME lint PASSED'    else        err 'Phoenix-E AME lint FAILED'        exit 1    fi}#----------------------------------------------------------------------------# v6.2 Phoenix+ Lint#----------------------------------------------------------------------------function lint_phoenix_plus() {    info '[6/7] Linting Phoenix+ TPE+AME v6.2...'    ${VERILATOR} --lint-only -Wall -Wno-DECLFILENAME -Wno-WIDTHTRUNC -Wno-WIDTHEXPAND        -I${ROOT_DIR}/v6_2_phoenix_plus/rtl        ${ROOT_DIR}/v6_2_phoenix_plus/rtl/orca_tpe_v6_2.sv        --top-module orca_tpe_v6_2        2>&1 | tee ${ROOT_DIR}/build/phoenix_plus/lint_tpe.log    if [ ${PIPESTATUS[0]} -eq 0 ]; then        ok 'Phoenix+ TPE lint PASSED'    else        err 'Phoenix+ TPE lint FAILED'        exit 1    fi    ${VERILATOR} --lint-only -Wall -Wno-DECLFILENAME -Wno-WIDTHTRUNC -Wno-WIDTHEXPAND        -I${ROOT_DIR}/v6_2_phoenix_plus/rtl        ${ROOT_DIR}/v6_2_phoenix_plus/rtl/orca_ame_v6_2.sv        --top-module orca_ame_v6_2        2>&1 | tee ${ROOT_DIR}/build/phoenix_plus/lint_ame.log    if [ ${PIPESTATUS[0]} -eq 0 ]; then        ok 'Phoenix+ AME lint PASSED'    else        err 'Phoenix+ AME lint FAILED'        exit 1    fi}#----------------------------------------------------------------------------# Integration Module Lint#----------------------------------------------------------------------------function lint_integration() {    info '[7/7] Linting SoC integration modules...'    for f in ${ROOT_DIR}/*/integration/*.sv; do        mod=$(basename $f .sv)        info '  Linting ${mod}...'        ${VERILATOR} --lint-only -Wall -Wno-DECLFILENAME            -I$(dirname $f)/../rtl            $f            --top-module ${mod}            2>&1 | tee ${ROOT_DIR}/build/$(basename $(dirname $(dirname $f)))/lint_${mod}.log        if [ ${PIPESTATUS[0]} -ne 0 ]; then            err 'Integration module ${mod} lint FAILED'            exit 1        fi    done    ok 'All integration modules lint PASSED'}#----------------------------------------------------------------------------# Run targets#----------------------------------------------------------------------------case ${TARGET} in    kestrel)        lint_kestrel        ;;    falcon)        lint_falcon        ;;    hawk)        lint_hawk        ;;    phoenix)        lint_phoenix        ;;    phoenix-e)        lint_phoenix_e        ;;    phoenix-plus)        lint_phoenix_plus        ;;    lint)        lint_kestrel        lint_falcon        lint_hawk        lint_phoenix        lint_phoenix_e        lint_phoenix_plus        lint_integration        ;;    all|*)        lint_kestrel        lint_falcon        lint_hawk        lint_phoenix        lint_phoenix_e        lint_phoenix_plus        lint_integration        ;;esac#----------------------------------------------------------------------------# Summary#----------------------------------------------------------------------------echo ''echo '=============================================================='echo '  Build Summary'echo '=============================================================='ok 'All lint checks completed successfully!'echo ''echo 'Generated files:'find ${ROOT_DIR}/build -name '*.log' -exec echo '  {}' ;echo ''echo 'Next steps:'echo '  1. Review lint logs in build/*/lint*.log'echo '  2. Run simulation: cd tb && make sim'echo '  3. Synthesize: cd scripts && vivado -mode batch -source synth.tcl'echo ''